<?php

declare(strict_types=1);

namespace Platform\UiNavigation;

use Illuminate\Contracts\Auth\Authenticatable;
use Illuminate\Support\Facades\Gate;
use Platform\UiNavigation\Contracts\MenuProviderInterface;
use Platform\UiNavigation\Contracts\NavigationBadgeProviderInterface;

/**
 * Builds the final navigation menu by merging providers,
 * filtering by capability visibility, and attaching badge counts.
 *
 * This class lives in the package (internal, not in Contracts/)
 * and has ZERO App\* imports.
 */
class NavigationBuilder
{
    /** @var array<MenuProviderInterface> */
    private array $menuProviders = [];

    /** @var array<NavigationBadgeProviderInterface> */
    private array $badgeProviders = [];

    /**
     * @param array<MenuProviderInterface> $menuProviders
     * @param array<NavigationBadgeProviderInterface> $badgeProviders
     */
    public function __construct(array $menuProviders = [], array $badgeProviders = [])
    {
        $this->menuProviders = $menuProviders;
        $this->badgeProviders = $badgeProviders;
    }

    /**
     * Build the complete navigation menu for the given user.
     *
     * @param Authenticatable $user
     * @param int|null $tenantId
     * @return array<int, array<string, mixed>>
     */
    public function build(Authenticatable $user, ?int $tenantId = null): array
    {
        // 1. Collect items from all providers
        $allItems = $this->collectItems($user, $tenantId);

        // 2. Collect badge counts from all providers
        $badges = $this->collectBadges($user, $tenantId);

        // 3. Filter by capability visibility and attach badges
        $menu = $this->filterAndDecorate($allItems, $badges, $user);

        // 4. Sort by order
        usort($menu, fn(array $a, array $b) => ($a['order'] ?? 999) <=> ($b['order'] ?? 999));

        return $menu;
    }

    /**
     * Collect menu items from all registered providers.
     *
     * @return array<int, array<string, mixed>>
     */
    private function collectItems(Authenticatable $user, ?int $tenantId): array
    {
        $items = [];
        foreach ($this->menuProviders as $provider) {
            $items = array_merge($items, $provider->items($user, $tenantId));
        }
        return $items;
    }

    /**
     * Collect badge counts from all registered badge providers.
     *
     * @return array<string, int>
     */
    private function collectBadges(Authenticatable $user, ?int $tenantId): array
    {
        $badges = [];
        foreach ($this->badgeProviders as $provider) {
            foreach ($provider->badges($user, $tenantId) as $key => $count) {
                $badges[$key] = ($badges[$key] ?? 0) + $count;
            }
        }
        return $badges;
    }

    /**
     * Filter items by capability and attach badge counts.
     *
     * @param array<int, array<string, mixed>> $items
     * @param array<string, int> $badges
     * @param Authenticatable $user
     * @return array<int, array<string, mixed>>
     */
    private function filterAndDecorate(array $items, array $badges, Authenticatable $user): array
    {
        $result = [];

        foreach ($items as $item) {
            // Capability-based visibility check
            if (isset($item['capability']) && $item['capability'] !== '') {
                if (!Gate::forUser($user)->allows($item['capability'])) {
                    continue;
                }
            }

            // Attach badge count if item has a badge_key
            if (isset($item['badge_key']) && isset($badges[$item['badge_key']])) {
                $item['badge'] = $badges[$item['badge_key']];
            }

            // Recursively filter sub-items for sections
            if (isset($item['type']) && $item['type'] === 'section' && isset($item['items'])) {
                $filteredChildren = $this->filterAndDecorate($item['items'], $badges, $user);
                if (empty($filteredChildren)) {
                    continue; // Hide sections with no visible children
                }
                $item['items'] = $filteredChildren;

                // Aggregate child badges for section badge
                $sectionBadge = 0;
                foreach ($filteredChildren as $child) {
                    $sectionBadge += $child['badge'] ?? 0;
                }
                if ($sectionBadge > 0) {
                    $item['badge'] = $sectionBadge;
                }
            }

            $result[] = $item;
        }

        return $result;
    }
}

